insert into public.contents (key, fr, en, section) values ('about.eyebrow', 'Notre maison', 'Our house', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.gal', 'L''atelier en images', 'The workshop in pictures', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.gros.p', 'Farafinatignɛ est spécialisée dans la production de masse et la vente en gros internationale. Nous offrons aux boutiques, aux distributeurs et aux institutions culturelles des produits authentiques, durables et adaptés au goût du marché contemporain, avec une logistique d''exportation maîtrisée.', 'Farafinatignɛ specialises in mass production and international wholesale. We supply shops, distributors and cultural institutions with authentic, durable products suited to contemporary taste, backed by a well-run export logistics chain.', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.gros.t', 'Vente en gros et exportation', 'Wholesale and export', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.h1a', 'L''Afrique de l''Ouest,', 'West Africa,', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.h1b', 'de la main à la main', 'hand to hand', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.intro', 'L''entreprise artisanale Farafinatignɛ fabrique et commercialise les objets traditionnels, les habits et les parures culturelles de nombreuses ethnies d''Afrique. Bijoux de cauris, de plastique recyclé, de métaux récupérés, de cuir et de pierres, bogolanfini : nous vous faisons découvrir le joyau de l''Afrique occidentale à travers l''art, l''histoire et la tradition.', 'Farafinatignɛ is a craft company that makes and sells the traditional objects, garments and cultural adornments of many African peoples. Jewellery of cowries, recycled plastic, reclaimed metals, leather and stones, bogolanfini: we let you discover the jewel of West Africa through art, history and tradition.', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.musee.p', 'À Mopti, Farafinatignɛ a ouvert un Musée des Perles, où sont rassemblées les perles anciennes d''Afrique de l''Ouest et la mémoire des routes commerciales du Delta intérieur. Le musée est <em>actuellement fermé pour raisons de sécurité</em> ; les collections, elles, continuent d''alimenter nos créations.', 'In Mopti, Farafinatignɛ opened a Bead Museum, gathering the antique beads of West Africa and the memory of the trade routes of the Inner Delta. The museum is <em>currently closed for security reasons</em>; the collections keep feeding our designs.', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.musee.t', 'Le Musée des Perles', 'The Bead Museum', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.s1.p', 'Notre atelier se tient à Mopti-Sévaré, sur la route nationale 6, au carrefour des routes qui montent vers le pays dogon et Tombouctou. C''est là que se rassemblent les pièces venues des forgerons, des teinturières et des tisserands de toute la région.', 'Our workshop stands in Mopti-Sévaré, on national road 6, where the roads to Dogon country and Timbuktu meet. This is where the pieces from smiths, dyers and weavers of the whole region come together.', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.s1.t', 'L''atelier de Sévaré', 'The Sévaré workshop', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.s2.p', 'Cauris du fleuve, laiton et bronze récupérés puis refondus à la cire perdue, tongs de plastique ramassées dans les rues de Mopti, cuir de chèvre tanné au village, coton filé main et teint à la boue fermentée ou à l''indigo. Rien n''arrive neuf, tout renaît.', 'Cowries from the river, brass and bronze reclaimed and recast by lost wax, plastic flip-flops picked up in the streets of Mopti, village-tanned goat leather, hand-spun cotton dyed with fermented mud or indigo. Nothing arrives new, everything is reborn.', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.s2.t', 'Les matières', 'The materials', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.s3.p', 'Un travail payé à son juste prix aux artisanes et artisans, des matières recyclées chaque fois que c''est possible, et des gestes transmis tels quels, sans machine intermédiaire. Vendre en gros, c''est faire durer ces gestes.', 'Fair pay for the women and men who make the pieces, recycled materials whenever possible, and gestures passed on unchanged, with no machine in between. Selling wholesale is how those gestures survive.', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.s3.t', 'Nos engagements', 'Our commitments', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.savoir.a.p', 'Colliers, bracelets, bagues et boucles d''oreilles. Nous créons constamment des nouveautés adaptées aux nouvelles générations, en fusionnant les tendances actuelles avec l''originalité de la culture malienne.', 'Necklaces, bracelets, rings and earrings. We constantly design new pieces for younger generations, blending current trends with the originality of Malian culture.', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.savoir.a.t', 'Bijoux ethniques & créations', 'Ethnic jewellery & creations', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.savoir.b.p', 'Nous intégrons une forte dimension écologique dans notre production en recyclant de nombreux matériaux — laiton, bronze, cuivre, plastique, boîtes de conserve — pour les transformer en accessoires de mode uniques.', 'We build a strong ecological dimension into our production by recycling many materials — brass, bronze, copper, plastic, tin cans — and turning them into one-of-a-kind fashion accessories.', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.savoir.b.t', 'Éco-responsabilité & recyclage ♻️', 'Eco-responsibility & recycling ♻️', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.savoir.c.p', 'Une expertise reconnue dans la teinture naturelle (bogolan) et une connaissance encyclopédique des perles africaines, transmise de Mopti à Djenné.', 'A recognised expertise in natural dyeing (bogolan) and an encyclopaedic knowledge of African beads, carried from Mopti to Djenné.', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.savoir.c.t', 'Bogolan & perlerie', 'Bogolan & beadwork', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.savoir.eyebrow', 'Savoir-faire', 'Know-how', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.savoir.lead', 'Nous maîtrisons des techniques ancestrales tout en restant tournés vers l''avenir.', 'We master ancestral techniques while keeping our eyes on what comes next.', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.savoir.t1', 'Entre tradition et modernité', 'Between tradition and modernity', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.story.dir', 'Direction générale : Issouf Cissé', 'Managing director: Issouf Cissé', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
