insert into public.contents (key, fr, en, section) values ('about.story.eyebrow', 'Notre histoire', 'Our story', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.story.fairs', 'ans de présence continue sur les salons internationaux', 'years of continuous presence at international trade fairs', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.story.p1', 'Farafinatignɛ a été fondée en mars 2000 par <b>Oumar Cissé</b>. Vingt-six ans plus tard, la maison est devenue une institution de l''artisanat malien, installée à Mopti-Sévaré, au carrefour des routes qui montent vers le pays dogon et Tombouctou.', 'Farafinatignɛ was founded in March 2000 by <b>Oumar Cissé</b>. Twenty-six years on, the house has become an institution of Malian craft, based in Mopti-Sévaré, where the roads to Dogon country and Timbuktu meet.', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.story.p2', 'Nous sommes aujourd''hui une équipe de <b>trente collaborateurs</b>. Nous ne sommes pas seulement des créateurs : nous sommes aussi des formateurs. Plusieurs générations d''artisanes et d''artisans maliens sont passées par nos ateliers, et c''est ainsi que les métiers d''art continuent de vivre dans le pays.', 'We are now a team of <b>thirty people</b>. We are not only makers: we are trainers too. Several generations of Malian craftswomen and craftsmen have passed through our workshops, and that is how the art trades stay alive in this country.', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.story.since', 'depuis mars 2000, sans interruption', 'since March 2000, without a break', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('about.story.t', 'Fondée en mars 2000', 'Founded in March 2000', 'about') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
