insert into public.contents (key, fr, en, section) values ('know.more', 'Notre histoire', 'Our story', 'know') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('know.p1', 'Les femmes bozo de Mopti rapportent les vieilles tongs abandonnées, les « tapettes ». Elles les lavent, les découpent, puis chauffent les morceaux au charbon ardent jusqu''à obtenir une pâte modelable.', 'The Bozo women of Mopti collect discarded flip-flops, locally called "tapettes". They wash them, cut them up, then heat the pieces over glowing charcoal until they become a mouldable paste.', 'know') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('know.p2', 'Cette pâte est enroulée autour de tiges de fer, les deux bouts sont soudés à la main : le bracelet est né. Le même geste, répété depuis deux générations, fait vivre des dizaines de familles à Mopti et Djenné.', 'That paste is wound around iron rods and the two ends are welded by hand: the bracelet is born. The same gesture, repeated for two generations, supports dozens of families in Mopti and Djenné.', 'know') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('know.stat1', 'douzaines de bracelets expédiées vers un seul client américain l''an passé', 'dozen bracelets shipped to a single American client last year', 'know') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('know.stat2', 'familles d''artisans et d''artisanes partenaires à Mopti et Djenné', 'partner artisan families in Mopti and Djenné', 'know') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('know.stat3', 'années d''atelier à Sévaré, sur la route nationale 6', 'years of workshop in Sévaré, on national road 6', 'know') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
