insert into public.contents (key, fr, en, section) values ('look.lead', 'Coiffes de cauris, bogolan porté, plastrons de cérémonie : les dernières pièces sorties de l''atelier de Sévaré.', 'Cowrie headpieces, bogolan worn, ceremonial breastplates: the latest pieces out of the Sévaré workshop.', 'look') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
