insert into public.contents (key, fr, en, section) values ('mani.eyebrow', 'Notre maison', 'Our house', 'mani') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('mani.lead', 'Depuis Mopti-Sévaré, nous fabriquons et exportons les objets, les parures et les étoffes de <em>nombreuses ethnies d''Afrique de l''Ouest</em>.', 'From Mopti-Sévaré, we make and export the objects, adornments and cloths of <em>many West African peoples</em>.', 'mani') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('mani.p1', 'Cauris du fleuve, laiton et bronze refondus à la cire perdue, tongs de plastique ramassées dans les rues, cuir de chèvre tanné au village, coton filé main et peint à la boue fermentée : rien n''arrive neuf, tout renaît entre les mains de nos artisanes et artisans.', 'Cowries from the river, brass and bronze recast by lost wax, plastic flip-flops picked up in the streets, village-tanned goat leather, hand-spun cotton painted with fermented mud: nothing arrives new, everything is reborn in the hands of our artisans.', 'mani') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('mani.p2', 'Nous ne vendons qu''en gros, à des boutiques, des créateurs et des importateurs. C''est ce qui permet de payer le travail à son juste prix et de faire vivre les gestes, saison après saison.', 'We sell wholesale only, to shops, designers and importers. That is what lets us pay the work its fair price and keep these gestures alive, season after season.', 'mani') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
insert into public.contents (key, fr, en, section) values ('mani.quote', 'De Mopti et Djenné au reste du monde, depuis mars 2000.', 'From Mopti and Djenné to the rest of the world, since March 2000.', 'mani') on conflict (key) do update set fr = excluded.fr, en = excluded.en, section = excluded.section;
